 for(let f of p.funds){let order=p.orders.find(o=>o.id===f.record.orderId);if(order&&f.to&&f.to!=='split'&&order.to&&f.to!==order.to&&!f.reason.trim())add('流水 '+f.id+' 与订单归属不同，请说明代付、退款或部分调整依据。','funds');if(!['main','target','split'].includes(f.to))add('资金流水 '+f.id+' 尚未明确归属。','funds');if(f.to!=='main'&&(f.pending||f.record.status==='处理中'))add('资金流水 '+f.id+' 正在处理中，请先确认支付或退款结果。','funds');if(!Number.isFinite(Number(f.amount))||bpNum(f.amount)<0||bpNum(f.amount)>Math.abs(f.signed)+.001)add('资金流水 '+f.id+' 转移金额超过当前可归属金额。','funds');if((f.to==='split'||Math.abs(bpNum(f.amount)-Math.abs(f.signed))>.001)&&!f.reason.trim())add('资金流水 '+f.id+' 部分调整请填写依据。','funds')}
 for(let a of bpAccountMoves(c)){let acct=(c.correctionData.current.walletAccounts||[]).find(x=>x.id===a.id),sum=bpRound(a.opening+(acct?.entries||[]).reduce((s,f)=>s+pcPaymentAmount(f),0)+(c.correctionData.current.paymentAllocations||[]).filter(x=>x.accountId===a.id).reduce((s,x)=>s+bpNum(x.amount),0));if(Math.abs(sum-a.balance)>.01)add(a.label+' 余额与流水不一致，差异 '+money(a.balance-sum)+'，请先核实数据。','funds');if(a.move<-.001||a.move>a.balance+.001||a.frozenTo<0||a.frozenTo>a.frozen||a.frozenTo>a.move||a.move-a.frozenTo>a.balance-a.frozen+.001)add(a.label+' 的分配与当前可用、冻结余额不一致。','funds')}
 for(let k of ['records','services'])for(let r of p[k]){if(!['main','target'].includes(r.to))add('记录 '+r.id+' 尚未明确归属。','records');let order=p.orders.find(o=>o.id===r.record.orderId);if(order&&order.to&&r.to&&order.to!==r.to&&!r.reason.trim())add('记录 '+r.id+' 与关联订单归属不同，请说明依据。','records')}for(let s of p.services){if(s.repair!=='none'){let debit=p.assets.find(a=>a.id===s.record.assetId);if(!debit||bpNum(debit.record.consumed)<bpNum(s.record.qty))add('服务 '+s.id+' 的原扣减资产不在当前可核实范围或已消费数量不足，请核实跨档案权益关联后处理。','records')}if(!s.actualEmployee.trim())add('服务 '+s.id+' 请核实实际服务员工。','records');if((s.repair!=='none'||s.actualEmployee!==(s.record.employee||''))&&!s.reason.trim())add('服务 '+s.id+' 修改扣减来源需填写依据。','records');if(s.repair==='replace'&&(!s.replacementAssetId||s.replacementAssetId===s.record.assetId))add('服务 '+s.id+' 请选择正确的扣减资产。','records');if(s.repair==='receivable'&&(!(bpNum(s.receivable)>0)||!Number.isFinite(Number(s.receivable))))add('服务 '+s.id+' 请填写经核实的待补收金额。','records');let row=p.assets.find(a=>a.id===(s.repair==='replace'?s.replacementAssetId:s.record.assetId));if(row&&s.repair!=='receivable'&&s.to&&row.to&&row.to!=='split'&&s.to!==row.to&&!s.reason.trim())add('服务 '+s.id+' 与资产归属不同，请说明代付、赠与或扣减纠正依据。','records')}
