 bonus.entries.push(sample('BONUS-1',{type:'示例赠送金入账',amount:200,at:stamp,bankPosting:false,status:'已完成'}),sample('BONUS-2',{type:'示例赠送金消耗',amount:-50,orderId:second.id,at:'2026-10-11 14:00:00',bankPosting:false,status:'已完成'}),sample('BONUS-3',{type:'示例赠送金失效',amount:-50,at:'2026-10-13 00:00:00',bankPosting:false,status:'已完成'}));bonus.balance=bpRound(bpNum(bonus.balance)+100);bonus.expired=bpRound(bpNum(bonus.expired)+50);
