function qaSourceData(source){let original=cxSourceData(source),live=bpResolveLive(source.cus);if(live?.acceptanceFixtureVersion)return {...clone(original),current:clone(live),demo:false};return original}
function qaUpgradeDraft(draft){
 let c=draft.plan;if(!c?.correctionData||draft.acceptanceFixtureVersion||qaComplete(c.correctionData.current))return;
 draft.acceptanceOriginalPlan=clone(c);let live=bpResolveLive(c.cus),base=c.correctionData.current;
 if(live?.acceptanceFixtureVersion&&qaMatchesBase(base,live))c.correctionData.current=clone(live);else qaEnrichProfile(base,'draft:'+draft.id);
 if(c.businessVersion===5){let fresh=clone(c);delete fresh.businessPlan;fresh.businessVersion=0;bpEnsure(fresh);let p=c.businessPlan;
  for(let key of ['orders','assets','funds','records','services','staff','accounts']){p[key]||=[];for(let row of fresh.businessPlan[key]){let existing=p[key].find(x=>x.id===row.id);if(existing){if(row.record)existing.record=clone(row.record);if(key==='accounts')for(let k of ['balance','frozen','expired','opening'])existing[k]=row[k];continue}let added=clone(row);if(['orders','assets','funds','records','services'].includes(key)){added.to='main';added.reason='';if(key==='assets'){added.qty=0;added.frozen=0}}p[key].push(added)}}
  for(let kind of ['asset','wallet','staff'])if(p[kind+'Evidence']==='pending')p[kind+'Evidence']='provided';
 }
 draft.acceptanceFixtureVersion=1;
}
function qaMatchesBase(base,live){let original=state.acceptanceFixtureBases?.['customer:'+live.id];if(!original)return false;let clean=x=>{let value=clone(x);for(let key of ['lastMerge','businessReady','demo'])delete value[key];let sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;return JSON.stringify(sort(value))};return clean(base)===clean(original)}
function qaInitialize(){
 if(state.acceptanceFixturesVersion===1)return;
 let protectedIds=new Set(state.cases.filter(c=>c.workflowVersion===4&&c.approvedPlan&&!c.bpResult&&!['已终止','已完成'].includes(c.status)).flatMap(c=>[c.cus,c.newId,c.businessPlan?.targetId]).filter(Boolean));
 for(let record of state.mergeRecords||[]){if(record.revoked)continue;let live=bpResolveLive(record.plan.mainId);if(!live&&!protectedIds.has(record.plan.mainId)){live=clone(record.snapshot.after);live.lastMerge=record.id;state.mergeCustomers.push(live)}if(live&&!protectedIds.has(live.id))qaEnrichProfile(live,'customer:'+live.id)}
 for(let source of state.mergeSources||[]){if(bpResolveLive(source.cus)||protectedIds.has(source.cus))continue;let live=clone(cxSourceData(source).current);qaEnrichProfile(live,'customer:'+live.id);live.businessReady=true;state.mergeCustomers.push(live)}
 for(let draft of state.correctionDrafts||[])qaUpgradeDraft(draft);
 for(let c of state.cases||[]){let original=c.submittedPlan?.correctionData?.current||c.correctionData?.current;if(qaComplete(original))continue;let live=bpResolveLive(c.cus),profile=clone(live||original||cxSourceData(c).current);qaEnrichProfile(profile,'case:'+c.id);c.acceptanceBusinessView={version:1,profile}}
 state.acceptanceFixturesVersion=1;persist();
}
let cxWorkbenchId=null,cxWorkbenchStage=null,cxWorkbenchResetScroll=false,cxWorkbenchTrigger=null,cxWorkbenchBackgroundScroll=0;
let apTask=null,apSheet=null,apView='merge',apFilters={},apApplied={},apPage=1;
const AP_ACTORS=['店长','市场部主管','总部运营','财务加签人'],apJobs=new Map();
function apReviewer(o=apObj()){return o?.resultData&&o.status!=='已完成'?'财务加签人':o?.review?.assignee||'审核人'}
function apIsMobile(){return ['mobile-approvals','mobile-approval','mobile-adjustment','mobile-store'].includes(route)}
function apItem(kind,id){return (kind==='merge'?state.mergeApplications:state.cases).find(x=>x.id===id)}
function apObj(){return apTask?apItem(apTask.kind,apTask.id):null}
function apEvent(o,action,note='',actor=apReviewer(o)){o.review.events.push({at:now(),actor,action,note});}
function apSeal(o,kind,system=false){if(o.review)return;o.review={version:1,status:'pending',assignee:kind==='correction'&&o.high?'市场部主管':'店长',urgency:o.urgency||'普通',submittedAt:o.submittedAt||o.time||o.date||now(),submittedBy:system?'系统':o.author||'门店人员',events:[],submittedPlan:clone(kind==='merge'?o.plan:o.submittedPlan),submittedPair:kind==='merge'?clone(o.pair):null};if(kind==='merge'){o.status='待审核';o.review.baseline=Object.fromEntries(o.pair.map(c=>[c.id,JSON.stringify(state.mergeCustomers.find(x=>x.id===c.id)||null)]));}apEvent(o,'提交审核',system?'前置规则拦截，系统生成合并工单':'提交完整方案，等待审核',o.review.submittedBy)}
function apSeedExamples(){if(state.approvalExamplesVersion===1)return;for(let [sourceId,suffix] of [['source-0','H'],['source-1','N']]){let source=cxSources().find(x=>x.id===sourceId);if(!source||state.cases.some(x=>x.review&&x.merge===source.merge))continue;let c=clMakePlan(source),p=c.businessPlan,order=p.orders.find(o=>o.id.endsWith('ORDER-1'));if(!order)continue;c.profileDraft={name:c.subname,phone:suffix==='H'?'13900008881':'13900008882',gender:'',birthday:'',remark:'已核实本次客户身份'};p.targetStore=c.store;order.to='target';order.reason='核对实际到店人与付款凭证，确认该订单属于本次客户';for(let k of ['funds','records','services'])for(let x of p[k])if(x.record.orderId===order.id){x.to='target';x.reason='随已核实的关联订单迁移'}for(let x of p.assets)if(x.record.orderId===order.id){x.to='target';x.qty=x.record.remaining;x.frozen=x.record.frozen||0;x.reason='随关联订单迁移剩余权益'}for(let k of ['orders','funds','records','services'])for(let x of p[k])if(!x.reason)x.reason='已逐项核对，保留当前档案归属';ctSyncPhone(c);if(bpValidate(c).length)continue;Object.assign(c,{id:clNextId('EC',state.cases),workflowVersion:4,status:'待审核',approval:0,step:5,submittedAt:now(),date:now(),newId:'',planReady:true,financeApproved:false,logs:[],demo:true,approvalExample:true,urgency:c.high?'紧急':'普通',description:'示例：核对合并后新增的护理订单、收款及退款凭证，将该订单及剩余权益、关联资金和回访记录归入本次新档案，原员工归属保留。'});c.amount=apFinanceTotal(c);c.submittedPlan=clPlanSnapshot(c);apSeal(c,'correction');state.cases.unshift(c)}state.approvalExamplesVersion=1;persist()}
function apResumeJobs(){for(let a of state.mergeApplications)if(a.review?.status==='approved'&&!a.recordId&&['已通过','执行中'].includes(a.status)){a.status='已通过';apScheduleMerge(a.id)}}
function apInit(){if(state.approvalWorkflowVersion===1){apSeedExamples();apResumeJobs();return;}for(let a of state.mergeApplications)if(!a.recordId&&!a.supersededBy&&['待审核','已通过','执行失败'].includes(a.status))apSeal(a,'merge',a.requestSource==='system');for(let g of state.mergeCandidates){let pair=mcMembers(g);if(!g.excluded&&g.hits.length&&pair.length>=2&&!state.mergeApplications.some(a=>a.candidateId===g.id||mrPairKey(a.pair)===mrPairKey(pair))){let a={id:mrNext('MA',state.mergeApplications),pair:clone(pair),rule:clone(g.rule),plan:mrPlan(pair,g.rule),status:'待审核',source:'系统拦截',trigger:g.trigger,match:g.match,candidateId:g.id,requestSource:'system',reasonType:'前置规则拦截',reason:g.basis,reasons:g.hits.map(h=>h.reason),evidence:[],author:'系统',store:pair[0].store,time:g.time,logs:[],demo:true};apSeal(a,'merge',true);state.mergeApplications.unshift(a)}}state.approvalWorkflowVersion=1;apSeedExamples();apResumeJobs();persist()}
function apClose(){apTask=null;apSheet=null;render();if(apIsMobile())$('.ap-mobile-scroll').scrollTop=apOpen.listScroll||0}
function apFinanceTotal(c){return c.businessVersion===5?bpRound(c.businessPlan.funds.reduce((n,f)=>n+Math.abs(bpChosenAmount(f)),0)):flowTotal(c)}
function apScheduleMerge(id){if(apJobs.has(id))return;apJobs.set(id,setTimeout(()=>{apJobs.delete(id);apExecuteMerge(id)},400))}
function apExecuteMerge(id){if(!PCCustomerStorage.locked)return customerExecute(id,()=>apExecuteMerge(...arguments));let a=apItem('merge',id);if(!a||a.review?.status!=='approved'||a.recordId||a.status==='执行中')return false;a.status='执行中';try{if(mrApplicationConflict(a)||Object.entries(a.review.baseline||{}).some(([id,data])=>JSON.stringify(state.mergeCustomers.find(c=>c.id===id)||null)!==data))throw Error('提交后客户档案或订单数据已变化，未迁移数据；需重新核实并提交审批');let plan=clone(a.review.approvedPlan),r=mrBuildRecord(a.pair,plan,a.rule,{method:'人工合并',trigger:a.trigger,match:a.match,applicationId:a.id,author:a.approvedBy||'审核人'}),impact=mrImpact(a.pair,plan);pcStampImpact(impact.after,r.id);r.candidateId=a.candidateId||'';r.approvalSnapshot=clone(a.review);for(let old of state.mergeRecords)if(!old.revoked&&old.pair.some(c=>a.pair.some(x=>x.id===c.id)))old.followUp=true;for(let c of a.pair){let i=state.mergeCustomers.findIndex(x=>x.id===c.id);if(i>=0)state.mergeCustomers[i]=c.id===impact.main.id?{...clone(impact.after),lastMerge:r.id}:{...clone(c),status:'已合并-从属',mergedInto:impact.main.id,lastMerge:r.id}}a.status='已执行';a.recordId=r.id;a.executedAt=r.time;apEvent(a,'系统执行完成','生成合并记录 '+uiId(r.id),'系统');mrEvent(a,'审核通过后系统执行完成，生成记录 '+r.id,'系统');state.mergeRecords.unshift(r);let g=state.mergeCandidates.find(g=>g.id===a.candidateId);if(g)mrEvent(g,'审核通过后执行合并 '+r.id,'系统');persist()}catch(e){if(e.customerStorage)throw e;customerRollback();a=apItem('merge',id);a.status='执行失败';a.review.executionError=e.message;apEvent(a,'执行失败',e.message,'系统');persist();render();return false}render();toast('审核通过，系统合并已完成');return true}
function customerGo(r,id){if(typeof msLeaving==='function'&&msLeaving(r,id))return;apTask=null;apSheet=null;if(FLOW_ROUTES.includes(r)){cxOpenWorkbench(id||activeId);return}if(r==='tickets'&&cxWorkbenchId&&route==='tickets'){cxCloseWorkbench();return}cxWorkbenchId=null;if(r==='new'){cxOpenApplication();return}cxApplicationOpen=false;mrTask=null;historyProfileId=null;if(isMergeRoute(r)){if(mergeEditor&&r!=='rules'){route=r;mergeRuleTab=mergeTabFor(r);render();return}mergeEditor=null;arbEditing=null;route='rules';let h='#rules';if(location.hash===h)render();else location.hash=h}else{mergeEditor=null;arbEditing=null;configDraft=clone(state.config);if(FLOW_ROUTES.includes(r)&&!id)id=activeId;if(id)activeId=id;let h='#'+r+(id?'?id='+encodeURIComponent(id):'');if(location.hash===h)render();else location.hash=h}$('#sidebar').classList.remove('open');syncSidebarControls();window.scrollTo(0,0)}
function customerReadRoute(){apTask=null;apSheet=null;cxWorkbenchId=null;cxWorkbenchStage=null;cxApplicationOpen=false;mrTask=null;historyProfileId=null;let [r,query]=location.hash.slice(1).split('?'),params=new URLSearchParams(query||'');if(isMergeRoute(r)||!pageMap.some(p=>p[0]===r)){route='rules';mergeEditor=null;arbEditing=null;configDraft=clone(state.config);if(location.hash!=='#rules')window.history.replaceState(null,'','#rules')}else{route=r;mergeEditor=null;arbEditing=null;configDraft=clone(state.config)}if(r==='reversal-detail'){route='reversals';window.history.replaceState(null,'','#reversals');setTimeout(()=>pcOpenReversal(params.get('id')||activeReversal||allReversals()[0]?.id),0)}if(r==='new'){route='tickets';cxApplicationOpen=true;window.history.replaceState(null,'','#tickets')}let id=params.get('id');if(id&&state.cases.some(c=>c.id===id))activeId=id;if(['mobile-approval','mobile-adjustment'].includes(r)&&id&&state.cases.some(c=>c.id===id)){apOpen('correction',id);customerRender();return}if(FLOW_ROUTES.includes(r)){route='tickets';cxWorkbenchId=activeId;cxWorkbenchResetScroll=true;window.history.replaceState(null,'','#tickets')}customerRender()}
