$('#brandMark').innerHTML=icon('layers');
const customerPages=new Map();let customerActionTurn=0;
function customerFeature(name,action,args){
 const turn=++customerActionTurn,origin=location.hash,current=PCApp.current;
 const context=()=>[mrTask,apTask,cxApplicationOpen,cxWorkbenchId,pcModalCustomer,pcRecordModalState,mrTask?.tab,apTask?.tab,apTask?.mobileTab,clStep];
 const initial=context(),valid=()=>turn===customerActionTurn&&origin===location.hash&&current===PCApp.current&&context().every((value,index)=>value===initial[index]);
 const required=[name];
 if(['pcGoCase','cxOpenWorkbench'].includes(action)&&state.cases.find(c=>c.id===args[0])?.review)required.push('customer-review');
 if(action==='mrOpen'&&args[0]==='application'&&state.mergeApplications.find(a=>a.id===args[1])?.review)required.push('customer-review');
 if(required.every(key=>PCModules[key]?.available))return PCModules[name].actions[action](...args);
 return Promise.all(required.map(key=>PCApp.loadModule(key))).then(()=>{if(valid())return PCModules[name].actions[action](...args)},error=>{if(valid())toast('页面功能加载失败：'+error.message)});
}
function customerRender(){
 if(typeof msIsMobile==='function'&&msIsMobile()){msRender();return}
 if(apIsMobile()){apRenderMobile();uiObserveIds();return}
 document.body.classList.remove('approval-h5');
 const scroll={};$$('[data-drawer-scroll]').forEach(el=>scroll[el.dataset.drawerScroll]=el.scrollTop);
 nav();const view=customerPages.get(route);if(!view&&!route.startsWith('mobile'))throw Error('客户页面未加载：'+route);
 const content=route.startsWith('mobile')?mobilePage():view();
 if(!cxWorkbenchId||!$('#main').children.length||$('#main>.pc-loading'))$('#main').innerHTML=(route.startsWith('mobile')?mobilePreviewTabs():'')+content+'<div class="app-footer">WEID微动 · 客户档案合并与纠错</div>';
 syncDrawerLayer($('#mergeDrawers'),'merge-record',mrTask?(mrTask.kind==='customer'?pcDrawer():mrTaskDrawer()):'');
 if(cxApplicationOpen)cxRenderApplication();else syncDrawerLayer($('#mergeDrawers'),'correction','');
 if(cxWorkbenchId)cxRenderWorkbench();else syncDrawerLayer($('#mergeDrawers'),'correction-workbench','');
 syncDrawerLayer($('#mergeDrawers'),'approval-review',apTask?apDrawer():'');syncDrawerInteraction();
 $$('[data-drawer-scroll]').forEach(el=>el.scrollTop=cxWorkbenchResetScroll&&el.dataset.drawerScroll==='correction-workbench'?0:scroll[el.dataset.drawerScroll]||0);
 cxWorkbenchResetScroll=false;movePageActions();document.title=(pageMap.find(p=>p[0]===route)?.[1]||'客户档案合并')+' · WEID微动';uiObserveIds();if(route.startsWith('mobile'))restoreMobilePreviewFocus()
}
function customerLeave(){customerActionTurn++;uiStopObservingIds();apTask=null;apSheet=null;cxWorkbenchId=null;cxWorkbenchStage=null;cxApplicationOpen=false;mrTask=null;historyProfileId=null;mergeEditor=null;arbEditing=null;$('#mergeDrawers').replaceChildren();syncDrawerInteraction()}
