function pcViewRecord(...args){return customerFeature('customer-merge','pcViewRecord',args)}
function mrOpen(...args){return customerFeature('customer-merge','mrOpen',args)}
function mrNew(...args){return customerFeature('customer-merge','mrNew',args)}
